import { test, expect } from '@playwright/test';

test.describe('Focus Indicators on Interactive Elements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/interactive-elements');
  });

  test('should display focus indicators on all interactive elements when tabbed through', async ({ page }) => {
    // Verify initial state with no focus
    const button = page.getByRole('button', { name: /submit/i });
    const input = page.getByLabel(/email/i);
    const checkbox = page.getByRole('checkbox', { name: /terms/i });
    const select = page.getByRole('combobox', { name: /country/i });
    const textarea = page.getByLabel(/feedback/i);

    await expect(button).not.toBeFocused();
    await expect(input).not.toBeFocused();
    await expect(checkbox).not.toBeFocused();
    await expect(select).not.toBeFocused();
    await expect(textarea).not.toBeFocused();

    // Tab through elements
    await button.press('Tab');
    await expect(button).toBeFocused();
    await expect(button).toHaveClass(/focus-indicator/);

    await input.press('Tab');
    await expect(input).toBeFocused();
    await expect(input).toHaveClass(/focus-indicator/);

    await checkbox.press('Tab');
    await expect(checkbox).toBeFocused();
    await expect(checkbox).toHaveClass(/focus-indicator/);

    await select.press('Tab');
    await expect(select).toBeFocused();
    await expect(select).toHaveClass(/focus-indicator/);

    await textarea.press('Tab');
    await expect(textarea).toBeFocused();
    await expect(textarea).toHaveClass(/focus-indicator/);

    // Verify focus indicator is visible on all elements
    const focusStyles = page.getByRole('button').evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const inputFocusStyles = page.getByLabel(/email/i).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const checkboxFocusStyles = page.getByRole('checkbox', { name: /terms/i }).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const selectFocusStyles = page.getByRole('combobox', { name: /country/i }).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const textareaFocusStyles = page.getByLabel(/feedback/i).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));

    expect(focusStyles).toBeDefined();
    expect(inputFocusStyles).toBeDefined();
    expect(checkboxFocusStyles).toBeDefined();
    expect(selectFocusStyles).toBeDefined();
    expect(textareaFocusStyles).toBeDefined();

    // Verify focus indicator is visible and styled correctly
    expect(focusStyles).toBe('rgb(255, 0, 0)');
    expect(inputFocusStyles).toBe('rgb(255, 0, 0)');
    expect(checkboxFocusStyles).toBe('rgb(255, 0, 0)');
    expect(selectFocusStyles).toBe('rgb(255, 0, 0)');
    expect(textareaFocusStyles).toBe('rgb(255, 0, 0)');

    // Verify focus indicator is removed when losing focus
    await input.press('ArrowUp');
    await expect(input).not.toHaveClass(/focus-indicator/);
  });

  test('should not display focus indicators on disabled elements', async ({ page }) => {
    // Verify initial state with no focus indicators on disabled elements
    const disabledButton = page.getByRole('button', { name: /submit/i });
    const disabledInput = page.getByLabel(/email/i);
    const disabledCheckbox = page.getByRole('checkbox', { name: /terms/i });
    const disabledSelect = page.getByRole('combobox', { name: /country/i });
    const disabledTextarea = page.getByLabel(/feedback/i);

    await expect(disabledButton).not.toBeFocused();
    await expect(disabledInput).not.toBeFocused();
    await expect(disabledCheckbox).not.toBeFocused();
    await expect(disabledSelect).not.toBeFocused();
    await expect(disabledTextarea).not.toBeFocused();

    // Verify focus indicators are not displayed on disabled elements
    const disabledButtonFocusStyles = page.getByRole('button', { name: /submit/i }).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const disabledInputFocusStyles = page.getByLabel(/email/i).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const disabledCheckboxFocusStyles = page.getByRole('checkbox', { name: /terms/i }).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const disabledSelectFocusStyles = page.getByRole('combobox', { name: /country/i }).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));
    const disabledTextareaFocusStyles = page.getByLabel(/feedback/i).evaluate((el) => getComputedStyle(el).getPropertyValue('outline-color'));

    expect(disabledButtonFocusStyles).toBeUndefined();
    expect(disabledInputFocusStyles).toBeUndefined();
    expect(disabledCheckboxFocusStyles).toBeUndefined();
    expect(disabledSelectFocusStyles).toBeUndefined();
    expect(disabledTextareaFocusStyles).toBeUndefined();

    // Verify focus indicator is not visible on disabled elements
    await expect(disabledButton).not.toHaveClass(/focus-indicator/);
    await expect(disabledInput).not.toHaveClass(/focus-indicator/);
    await expect(disabledCheckbox).not.toHaveClass(/focus-indicator/);
    await expect(disabledSelect).not.toHaveClass(/focus-indicator/);
    await expect(disabledTextarea).not.toHaveClass(/focus-indicator/);
  });
});
